#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);policy=JSON.parse(File.read(File.join(root,'config/client-profile-allowlist.json')));profiles=Dir.glob(File.join(client,'profiles/v2/packages/*.json')).map{|p|File.basename(p)}.sort;builder=JSON.parse(File.read(File.join(client,'profiles/v2/packages/builder.json')));active=builder.dig('BuildTaskManager','taskMap').to_h.values.flat_map{|t|t.dig('options','packages').to_h.keys}.uniq;checks={creatorVersion:JSON.parse(File.read(File.join(client,'package.json'))).dig('creator','version')==policy['creatorVersion'],platformWhitelisted:builder.to_s.include?('web-desktop'),noForbiddenActivePlugin:(active&policy['forbiddenPlugins']).empty?,profilesExcludedFromSource:File.read(File.join(client,'.gitignore')).lines.map(&:strip).include?('/profiles/'),profilesExcludedFromRelease:policy['forbiddenPublicationRoots'].include?('profiles')&&!File.read(File.join(root,'config/release-allowlist.json')).include?('profiles')};report={schemaVersion:1,profiles:profiles,activePlugins:active,nonWhitelistedProfiles:profiles-policy['allowedProfilePackages'],checks:checks};out=File.join(root,'docs/generated/creal12-client-profiles.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort("CREAL12 failed: #{checks}")unless checks.values.all?;puts 'CREAL12 PASS: Creator profiles isolated and publication-whitelisted'
